from pathlib import Path

EDITORIAL = Path("insight_desk/pipeline/editorial.py")
TEST = Path("tests/test_kpop_promo_materiality.py")

def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(old, new, 1)

def main() -> None:
    text = EDITORIAL.read_text(encoding="utf-8")
    text = replace_once(text, '_LOW_VALUE_EVENT_TYPES = {\n    "LOW_VALUE_APPEARANCE",\n    "LOW_VALUE_POLL",\n    "ROUTINE_SCHEDULE",\n    "ROUTINE_MARKET_QUOTE",\n}', '_LOW_VALUE_EVENT_TYPES = {\n    "LOW_VALUE_APPEARANCE",\n    "LOW_VALUE_POLL",\n    "LOW_VALUE_PROMO_CONTENT",\n    "ROUTINE_SCHEDULE",\n    "ROUTINE_MARKET_QUOTE",\n}', "low-value event set")
    text = replace_once(text, '\n\ndef _is_routine_market_quote(title_text: str) -> bool:\n', '\n\n_KPOP_PROMO_CONTENT_MARKERS = (\n    "댄스 커버",\n    "댄스커버",\n    "커버 영상",\n    "커버영상",\n    "커버 무대",\n    "커버무대",\n    "댄스 챌린지",\n    "댄스챌린지",\n    "챌린지 영상",\n    "챌린지영상",\n    "퍼포먼스 영상",\n    "퍼포먼스영상",\n    "안무 영상",\n    "안무영상",\n    "숏폼 영상",\n    "숏폼영상",\n)\n_KPOP_MATERIAL_EVENT_PATTERNS = (\n    re.compile(r"(?:신곡|싱글|앨범|음원).{0,24}(?:발매|출시)"),\n    re.compile(r"컴백.{0,12}(?:확정|발표|한다|예정)"),\n    re.compile(r"(?:콘서트|공연|월드투어).{0,16}(?:개최|확정|발표|예정)"),\n    re.compile(r"(?:차트|빌보드).{0,16}(?:1위|진입|기록|돌파)"),\n    re.compile(r"(?:수상|대상|본상|신인상)"),\n    re.compile(r"(?:전속계약|계약).{0,16}(?:체결|종료|해지|갱신)"),\n)\n\n\ndef _is_low_value_kpop_promo_content(title_text: str, topic: Topic) -> bool:\n    """Reject promotional performance content that is not itself a material music event."""\n\n    topic_key = _compact(f"{topic.id} {topic.name}")\n    if "kpop" not in topic_key and "케이팝" not in topic_key:\n        return False\n    if not any(_contains(title_text, marker) for marker in _KPOP_PROMO_CONTENT_MARKERS):\n        return False\n\n    normalized = normalize_text(title_text)\n    material_event = any(pattern.search(normalized) for pattern in _KPOP_MATERIAL_EVENT_PATTERNS)\n    return not material_event\n\n\ndef _is_routine_market_quote(title_text: str) -> bool:\n', "promo helper insertion")
    text = replace_once(text, '    if is_low_value_popularity_poll(f"{title_text} {lead_text}"):\n        event_type, significance, matched_terms = "LOW_VALUE_POLL", 18.0, ["LOW_VALUE_POLL"]\n    elif _is_low_value_fan_event(title_text) or _is_low_value_kpop_institutional_event(title_text, topic):\n        event_type, significance, matched_terms = "LOW_VALUE_APPEARANCE", 20.0, ["LOW_VALUE_APPEARANCE"]', '    if is_low_value_popularity_poll(f"{title_text} {lead_text}"):\n        event_type, significance, matched_terms = "LOW_VALUE_POLL", 18.0, ["LOW_VALUE_POLL"]\n    elif _is_low_value_kpop_promo_content(title_text, topic):\n        event_type, significance, matched_terms = "LOW_VALUE_PROMO_CONTENT", 16.0, ["LOW_VALUE_PROMO_CONTENT"]\n    elif _is_low_value_fan_event(title_text) or _is_low_value_kpop_institutional_event(title_text, topic):\n        event_type, significance, matched_terms = "LOW_VALUE_APPEARANCE", 20.0, ["LOW_VALUE_APPEARANCE"]', "assess_event promo gate")
    EDITORIAL.write_text(text, encoding="utf-8")
    TEST.write_text('from __future__ import annotations\n\nimport unittest\n\nfrom insight_desk.domain.models import EvidenceType, NewsItem, Topic\nfrom insight_desk.pipeline.clustering import StoryCluster\nfrom insight_desk.pipeline.editorial import assess_cluster\n\n\ndef _topic(topic_id: str = "kpop", name: str = "엔터·음악·K-POP") -> Topic:\n    return Topic(\n        topic_id,\n        name,\n        True,\n        False,\n        70,\n        ("K-POP",),\n        candidate_budget=12,\n        intent_anchors=("K-POP", "가수", "그룹", "컴백", "앨범", "음원", "콘서트"),\n        negative_context=("광고", "협찬", "굿즈"),\n        event_terms=("발표", "공개", "앨범", "음원", "컴백", "공연", "콘서트", "수상", "계약"),\n    )\n\n\ndef _item(key: str, title: str, *, topic_id: str = "kpop", query: str = "K-POP") -> NewsItem:\n    return NewsItem(\n        evidence_id=key,\n        topic_id=topic_id,\n        query=query,\n        title=title,\n        summary=title,\n        original_url=f"https://fixture.test/{key}",\n        naver_url="",\n        canonical_url=f"https://fixture.test/{key}",\n        published_at="2026-08-21T06:30:00+09:00",\n        source_domain="fixture.test",\n        content_hash=key,\n        score=90.0,\n        metadata_title=title,\n        metadata_description=title,\n        provenance=(EvidenceType.SEARCH_SNIPPET, EvidenceType.ENRICHED_METADATA),\n        matched_topic_ids=(topic_id,),\n        retrieval_channels=("SIM",),\n        retrieval_queries=(query,),\n    )\n\n\nclass KpopPromoMaterialityTests(unittest.TestCase):\n    def test_promotional_performance_content_is_low_value(self) -> None:\n        topic = _topic()\n        titles = (\n            "권은비, 아이돌 신곡 댄스 커버 공개",\n            "아이브, 신예 그룹 댄스 챌린지 영상 공개",\n            "가수 A, 화제곡 커버 무대 선보여",\n            "그룹 B, 퍼포먼스 영상 공개",\n            "그룹 C, 신곡 안무 영상 공개",\n        )\n        for index, title in enumerate(titles):\n            assessment = assess_cluster(\n                StoryCluster("kpop", (_item(f"promo-{index}", title),)),\n                topic,\n                novelty="NEW",\n            )\n            self.assertEqual(assessment.event.event_type, "LOW_VALUE_PROMO_CONTENT", title)\n            self.assertFalse(assessment.event.passed, title)\n            self.assertFalse(assessment.qualified, title)\n            self.assertIn("LOW_VALUE_EVENT", assessment.event.reasons, title)\n\n    def test_comeback_background_does_not_rescue_a_cover_story(self) -> None:\n        topic = _topic()\n        title = "컴백 앞둔 권은비, 아이돌 신곡 댄스 커버 공개"\n        assessment = assess_cluster(\n            StoryCluster("kpop", (_item("comeback-background", title),)),\n            topic,\n            novelty="NEW",\n        )\n        self.assertEqual(assessment.event.event_type, "LOW_VALUE_PROMO_CONTENT")\n        self.assertFalse(assessment.qualified)\n\n    def test_material_release_with_secondary_performance_video_survives(self) -> None:\n        topic = _topic()\n        title = "권은비, 신곡 \'Hello\' 발매하며 컴백·퍼포먼스 영상 공개"\n        assessment = assess_cluster(\n            StoryCluster("kpop", (_item("material-release", title),)),\n            topic,\n            novelty="NEW",\n        )\n        self.assertNotEqual(assessment.event.event_type, "LOW_VALUE_PROMO_CONTENT")\n        self.assertTrue(assessment.event.passed)\n\n    def test_material_tour_announcement_with_secondary_challenge_survives(self) -> None:\n        topic = _topic()\n        title = "BTS, 월드투어 개최 발표·댄스 챌린지 영상 공개"\n        assessment = assess_cluster(\n            StoryCluster("kpop", (_item("material-tour", title),)),\n            topic,\n            novelty="NEW",\n        )\n        self.assertNotEqual(assessment.event.event_type, "LOW_VALUE_PROMO_CONTENT")\n        self.assertTrue(assessment.event.passed)\n\n    def test_non_kpop_video_publication_is_not_globally_blocked(self) -> None:\n        topic = Topic(\n            "ai_tech",\n            "AI·테크",\n            True,\n            False,\n            90,\n            ("OpenAI",),\n            candidate_budget=12,\n            intent_anchors=("OpenAI", "AI", "모델"),\n            negative_context=("광고",),\n            event_terms=("공개", "출시", "발표"),\n        )\n        title = "OpenAI, GPT-6 데모 영상 공개"\n        assessment = assess_cluster(\n            StoryCluster("ai_tech", (_item("ai-demo", title, topic_id="ai_tech", query="OpenAI"),)),\n            topic,\n            novelty="NEW",\n        )\n        self.assertNotEqual(assessment.event.event_type, "LOW_VALUE_PROMO_CONTENT")\n\n\nif __name__ == "__main__":\n    unittest.main()\n', encoding="utf-8")

if __name__ == "__main__":
    main()
